/**
 * Nitro plugin: wires the Cloudflare Cron Trigger to the background tick.
 *
 * The production build's Worker entry is generated by Nitro, and its
 * `scheduled()` handler only fires the "cloudflare:scheduled" hook — it never
 * called the `scheduled` export in src/server.ts. So the cron ran every few
 * minutes and did nothing: no sending, no inbox sync, no background scans.
 * This hook makes it do one tick (send what's due, sync inboxes, read websites).
 */
import { definePlugin } from "nitro";
import { resolveIntegrationEnv } from "../lib/integration-settings.server";
import { runTick } from "../lib/tick";

export default definePlugin((nitroApp) => {
  nitroApp.hooks.hook("cloudflare:scheduled", async ({ env }) => {
    const e = ((env ?? {}) as Record<string, string | undefined>);
    try {
      const configured = await resolveIntegrationEnv(e);
      const r = await runTick(configured, { trigger: "cron", origin: e.PUBLIC_ORIGIN });
      console.log("[outreach] tick", JSON.stringify({ sent: r.dispatch?.mailboxes.map((m) => [m.email, m.sent, m.skipped]), scans: r.scans, skipped: r.dispatch_skipped, errors: r.errors.slice(0, 5) }));
    } catch (err) {
      console.error("[outreach] tick failed", err);
    }
  });
});
